function geometryBuilder(){
  const pos=[];
  const tri=(a,b,c)=>pos.push(...a,...b,...c);
  const quad=(a,b,c,d)=>{tri(a,b,c);tri(a,c,d);};
  const finish=()=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.computeVertexNormals();return g;};
  return {tri,quad,finish};
}
function offsetPolygon(poly,d){
  return poly.map((p,i)=>{
    const a=poly[(i+poly.length-1)%poly.length],c=poly[(i+1)%poly.length];
    const u=[p[0]-a[0],p[1]-a[1]],v=[c[0]-p[0],c[1]-p[1]];
    const lu=Math.hypot(...u),lv=Math.hypot(...v);
    const n=[-u[1]/lu,u[0]/lu],m=[-v[1]/lv,v[0]/lv];
    const q=[p[0]+n[0]*d,p[1]+n[1]*d],r=[p[0]+m[0]*d,p[1]+m[1]*d];
    const den=u[0]*v[1]-u[1]*v[0];
    if(Math.abs(den)<1e-8)return q;
    const t=((r[0]-q[0])*v[1]-(r[1]-q[1])*v[0])/den;
    return [q[0]+u[0]*t,q[1]+u[1]*t];
  });
}
function plate(poly,depth,bev=0.004){
  const b=Math.min(bev,depth*0.32),small=offsetPolygon(poly,b),g=geometryBuilder();
  const loops=[small,poly,poly,small].map((p,i)=>p.map(q=>[q[0],q[1],[-depth/2,-depth/2+b,depth/2-b,depth/2][i]]));
  for(let k=0;k<3;k++)for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;g.quad(loops[k][i],loops[k][j],loops[k+1][j],loops[k+1][i]);}
  const cap=THREE.ShapeUtils.triangulateShape(small.map(p=>new THREE.Vector2(...p)),[]);
  for(const [a,b,c] of cap){g.tri(loops[0][c],loops[0][b],loops[0][a]);g.tri(loops[3][a],loops[3][b],loops[3][c]);}
  return g.finish();
}
function oct(w,h,c=0.035){return [[-w/2+c,-h/2],[w/2-c,-h/2],[w/2,-h/2+c],[w/2,h/2-c],[w/2-c,h/2],[-w/2+c,h/2],[-w/2,h/2-c],[-w/2,-h/2+c]];}
function group(parent,name,pos=[0,0,0],rot=[0,0,0]){const g=new THREE.Group();g.name=name;g.position.set(...pos);g.rotation.set(...rot.map(a=>a*Math.PI/180));parent.add(g);return g;}
function part(parent,name,geo,mat,pos=[0,0,0],rot=[0,0,0]){const p=createPart(name,geo,mat,{parent,position:pos,rotation:rot});p.name=name;return p;}
async function block(parent,name,s,pos,mat,r=0.06){return part(parent,name,await roundedBoxGeo(...s,Math.min(r,Math.min(...s)*0.3),{style:'chamfer'}),mat,pos);}
function panel(parent,name,w,h,d,c,pos,mat,rot=[0,0,0]){return part(parent,name,plate(oct(w,h,c),d,Math.min(d*0.25,0.025)),mat,pos,rot);}
function cyl(parent,name,r,h,pos,mat,rot=[0,0,0],seg=12,rBottom=r){return part(parent,name,cylinderGeo(r,rBottom,h,seg),mat,pos,rot);}
function tube(parent,name,points,r,mat,seg=20){
  const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)),false,'catmullrom',.2);
  return part(parent,name,new THREE.TubeGeometry(curve,seg,r,8,false),mat);
}
function mergeParts(parent){
  for(const c of [...parent.children])if(!(c instanceof THREE.Mesh))mergeParts(c);
  const buckets=new Map();
  for(const c of parent.children)if(c instanceof THREE.Mesh && !Array.isArray(c.material)){const key=c.material.uuid;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(c);}
  for(const meshes of buckets.values()){if(meshes.length<2)continue;const positions=[],normals=[];
    for(const mesh of meshes){mesh.updateMatrix();let g=mesh.geometry.clone();g.applyMatrix4(mesh.matrix);if(g.index)g=g.toNonIndexed();const p=g.getAttribute('position'),n=g.getAttribute('normal');for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));}g.dispose();}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
    const combined=new THREE.Mesh(g,meshes[0].material);combined.name=parent.name+'_'+meshes[0].material.name.replace(/[^a-zA-Z0-9_-]/g,'_');parent.add(combined);for(const mesh of meshes)parent.remove(mesh);
  }
}

const meta={name:'water-recycler',reference:'assets/source/phase-7/oxygen-maker.kiln.js (sibling station machine)'};

// Front (+X) faces the player. Water tank on -Z, filter cabinet on +Z, pump on the +Z end, outlet pipes drop off the back (-X).
const SKID={x0:-0.55,x1:0.72,y:0.12,z:1.72};
const CAB={x0:-0.45,x1:0.6,z0:-0.1,z1:0.62,y:1.42};
const TANK={x:0.04,z:-0.45,r:0.31,y0:0.12,h:1.42,water:0.98};
const SOCKET={y:1.0,z:0.25,r:0.11};
const LAMP={y:1.4,z:0.5};

async function build(){
  const root=createRoot('water-recycler'),m=styleMaterials();
  const water=gameMaterial(PALETTE['ice-pale'],{roughness:0.25,metalness:0,name:'water:ice-pale'});
  const waterTop=gameMaterial(PALETTE['accent-cyan'],{roughness:0.25,metalness:0,name:'water:accent-cyan'});
  const skidCx=(SKID.x0+SKID.x1)/2,skidLx=SKID.x1-SKID.x0;
  await block(root,'Slate skid',[skidLx,SKID.y-0.04,SKID.z],[skidCx,0.04+(SKID.y-0.04)/2,0],m.panelGray,0.04);
  for(const z of [-0.74,0.74])await block(root,'Skid foot '+z,[skidLx+0.05,0.04,0.18],[skidCx,0.02,z],m.trim,0.012);

  // Filter cabinet
  const cab=group(root,'cabinet');
  const cx=(CAB.x0+CAB.x1)/2,cz=(CAB.z0+CAB.z1)/2,cw=CAB.x1-CAB.x0,cd=CAB.z1-CAB.z0,top=SKID.y+CAB.y;
  await block(cab,'Ivory filter cabinet',[cw,CAB.y,cd],[cx,SKID.y+CAB.y/2,cz],m.panel,0.1);
  for(const y of [SKID.y+0.08,top-0.07])await block(cab,'Grey wrap band '+y.toFixed(2),[cw+0.05,0.13,cd+0.05],[cx,y,cz],m.panelGray,0.045);
  for(const x of [CAB.x0,CAB.x1])for(const z of [CAB.z0,CAB.z1])await block(cab,'Grey corner post '+x+z,[0.1,CAB.y-0.1,0.1],[x+(x<0?0.02:-0.02),SKID.y+CAB.y/2,z+(z<0?0.02:-0.02)],m.panelGray,0.03);

  // Front: orange service panel around the filter socket
  const fx=CAB.x1;
  panel(cab,'Orange service panel',0.6,0.6,0.04,0.09,[fx+0.01,SOCKET.y,SOCKET.z],m.accent,[0,90,0]);
  const sock=group(cab,'filter_socket',[fx+0.03,SOCKET.y,SOCKET.z]);
  cyl(sock,'Filter socket collar',SOCKET.r+0.045,0.07,[0.025,0,0],m.panelGray,[0,0,90],12);
  cyl(sock,'Filter socket recess',SOCKET.r,0.072,[0.026,0,0],m.trim,[0,0,90],12);
  for(const a of [45,135,225,315]){const r=SOCKET.r+0.075,t=a*Math.PI/180;cyl(sock,'Socket bolt '+a,0.016,0.02,[0.005,Math.sin(t)*r,Math.cos(t)*r],m.panelGray,[0,0,90],6);}
  // Lower intake grille
  panel(cab,'Grille recess',0.4,0.56,0.03,0.07,[fx+0.005,0.45,SOCKET.z],m.trim,[0,90,0]);
  for(let i=0;i<4;i++)await block(cab,'Grille slat '+i,[0.04,0.045,0.5],[fx+0.015,0.29+i*0.105,SOCKET.z],m.panelGray,0.01);
  // Status lamp housing; the game lights the lens
  const lamp=group(cab,'status_lamp',[fx,LAMP.y,LAMP.z]);
  await block(lamp,'Status lamp housing',[0.08,0.19,0.19],[0.04,0,0],m.panelGray,0.025);
  await block(lamp,'Status lamp hood',[0.07,0.03,0.21],[0.075,0.105,0],m.panelGray,0.01);
  cyl(lamp,'Status lamp lens',0.065,0.02,[0.09,0,0],m.trim,[0,0,90],10);

  // Top: vent box and filter cartridge rack
  await block(cab,'Top vent box',[0.5,0.12,0.4],[cx-0.08,top+0.06,cz+0.04],m.panelGray,0.04);
  for(let i=0;i<3;i++)await block(cab,'Vent slot '+i,[0.38,0.02,0.05],[cx-0.08,top+0.125,cz-0.08+i*0.12],m.trim,0.008);
  for(const z of [cz-0.1,cz+0.12])cyl(cab,'Spare cartridge '+z.toFixed(2),0.055,0.12,[cx+0.3,top+0.06,z],m.accent,[0,0,0],8);

  // Water tank on -Z
  const tk=group(root,'water_tank',[TANK.x,TANK.y0,TANK.z]);
  cyl(tk,'Tank base ring',TANK.r+0.05,0.14,[0,0.07,0],m.panelGray,[0,0,0],12,TANK.r+0.07);
  cyl(tk,'Tank glass',TANK.r,TANK.h-0.3,[0,0.14+(TANK.h-0.3)/2,0],m.glass,[0,0,0],16);
  cyl(tk,'Tank water',TANK.r-0.025,TANK.water-0.14,[0,0.14+(TANK.water-0.14)/2,0],water,[0,0,0],16);
  cyl(tk,'Water surface',TANK.r-0.02,0.035,[0,TANK.water,0],waterTop,[0,0,0],16);
  cyl(tk,'Filter standpipe',0.06,TANK.h-0.3-(TANK.water+0.02)+0.14,[0,(TANK.water+0.02+TANK.h-0.16)/2,0],m.trim,[0,0,0],8);
  cyl(tk,'Tank top band',TANK.r+0.04,0.1,[0,TANK.h-0.11,0],m.accent,[0,0,0],12);
  cyl(tk,'Tank dome',TANK.r*0.5,0.12,[0,TANK.h,0],m.panel,[0,0,0],12,TANK.r+0.04);
  cyl(tk,'Tank valve collar',0.08,0.07,[0,TANK.h+0.09,0],m.panelGray,[0,0,0],10);
  for(const a of [30,150,270]){const t=a*Math.PI/180,r=TANK.r+0.03;await block(tk,'Tank cage post '+a,[0.06,TANK.h-0.3,0.06],[Math.cos(t)*r,0.14+(TANK.h-0.3)/2,Math.sin(t)*r],m.panelGray,0.02);}
  cyl(tk,'Tank mid strap',TANK.r+0.045,0.06,[0,0.62,0],m.panelGray,[0,0,0],12);
  for(const y of [0.4,0.8])await block(tk,'Tank bracket '+y,[0.12,0.08,0.16],[0,y+0.02,TANK.r+0.07],m.panelGray,0.02);
  // Transfer line: tank top to cabinet top
  tube(root,'Clean water line',[[TANK.x,TANK.y0+TANK.h+0.12,TANK.z],[TANK.x,top+0.22,TANK.z+0.1],[TANK.x-0.05,top+0.18,0.0],[cx-0.08,top+0.12,0.05]],0.04,m.panelGray,12);

  // Outlet pipes leave the back (-X) and drop to the ground
  for(const [y,z] of [[1.15,0.06],[0.82,0.42]]){
    cyl(root,'Back pipe collar '+z,0.07,0.06,[CAB.x0-0.02,y,z],m.accent,[0,0,90],10);
    tube(root,'Back pipe '+z,[[CAB.x0,y,z],[CAB.x0-0.17,y-0.02,z],[-0.68,y-0.2,z],[-0.68,0.07,z]],0.045,m.panelGray,12);
    cyl(root,'Ground flange '+z,0.085,0.06,[-0.68,0.03,z],m.accent,[0,0,0],10);
  }

  // Pump on the +Z end
  const pz=0.76;
  const pump=group(root,'pump',[0.05,SKID.y,pz]);
  await block(pump,'Pump mount',[0.46,0.08,0.22],[0,0.04,0],m.trim,0.02);
  cyl(pump,'Pump motor',0.11,0.3,[-0.06,0.2,0],m.panel,[0,0,90],10);
  for(const x of [-0.17,0.05])cyl(pump,'Motor rib '+x,0.12,0.03,[x,0.2,0],m.panelGray,[0,0,90],10);
  cyl(pump,'Pump end cap',0.08,0.04,[-0.23,0.2,0],m.accent,[0,0,90],10);
  cyl(pump,'Pump volute',0.13,0.1,[0.15,0.2,0],m.accent,[0,0,90],12);
  tube(pump,'Pump feed line',[[0.15,0.32,0],[0.15,0.5,-0.02],[0.12,0.64,-0.1],[0.12,0.68,-0.12]],0.04,m.panelGray,8);
  cyl(pump,'Pump inlet collar',0.07,0.05,[0.12,0.68,-0.12],m.accent,[90,0,0],10);

  mergeParts(root);
  defineBudget({triangles:BUDGETS['medium-prop']},root);
  return root;
}
